import{z as s,x as l,o as E,c as B,q as r,j as n,D as e,d as o,s as A,S as i}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"TRACE 公司债成交报告","description":"","frontmatter":{"title":"TRACE 公司债成交报告","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/trace-corporate-bond.md","filePath":"quant/trace-corporate-bond.md","lastUpdated":1791063341000}'),p={name:"quant/trace-corporate-bond.md"};function d(c,a,C,T,h,u){const t=l("Mermaid");return E(),B("div",null,[a[2]||(a[2]=r('<h1 id="trace-公司债成交报告" tabindex="-1">TRACE 公司债成交报告 <a class="header-anchor" href="#trace-公司债成交报告" aria-label="Permalink to &quot;TRACE 公司债成交报告&quot;">​</a></h1><div class="epigraph"><p>TRACE 是成交报告系统，不是限价簿馈送。字段告诉你谁在何时报告了什么价格与规模，以及监管允许隐瞒多久、截断多少；它不告诉你当时能否再成交。</p><footer>—— 据 FINRA 对 TRACE 报告义务与披露规则的公开说明；经验含义见 Edwards, Harris and Piwowar, Journal of Finance, 2007</footer></div><p><a href="/quant/nbbo-construction">NBBO 构造</a>把股票保护报价拼成包络。<a href="/quant/bond-liquidity-trace">债券流动性与 TRACE</a>已经用打印估成本。<a href="/quant/corporate-bond-otc">公司债 OTC</a>写了 RFQ。本课作为数据源对照的收束：把 TRACE 当成<strong>报告契约</strong>——谁必须报、报哪些字段、大额如何截断与延迟、修订如何发生、研究文件与实时馈送有何差别。不重复流动性度量公式，不重复询价博弈。附录馈送课序到此结束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>股票磁带尽量接近撮合事件。TRACE 是经销商与报告方在规则时限内提交的成交报告，时间戳是报告时钟，不是股票引擎匹配时钟。大额曾被 cap、曾延迟对公众披露，研究数据集后来才提供更完整的字段。把 TRACE 当 ITCH 用——按报告顺序重建「簿」——对象不存在。缺口是读手册：强制报告的范围（哪些债券、哪些交易）、买卖标识是否存在、客户/经销商、主/次、取消与更正消息。没有这些，规模加权成本、方向、甚至成交笔数都会错。</p><p>实时公众馈送与学术用增强文件不是同一产品。用公众延迟馈送做「当时可交易信息集」，用增强文件做事后度量，必须拆开，否则回填式前视：你在 \\(t\\) 日用了当时公众还看不到的未截断面值。</p><h3 id="报告时间-成交时间-公众可见时间" tabindex="-1">报告时间 ≠ 成交时间 ≠ 公众可见时间 <a class="header-anchor" href="#报告时间-成交时间-公众可见时间" aria-label="Permalink to &quot;报告时间 ≠ 成交时间 ≠ 公众可见时间&quot;">​</a></h3><p>契约里至少三个时刻。成交发生、向 TRACE 报告、对公众披露。延迟披露规则使大额的公众可见时间晚于报告。研究若用披露时间当事件时间，冲击被平滑；若用成交时间但该字段填的是报告时间，事件研究的零点错了。必须按文件字典对齐。这与股票 SIP 的「匹配 vs 汇总」类似，但延迟是监管设计，不是物理一跳。</p><p><span class="marginnote">数字实例：一笔 500 万美元的大额债 10:00 成交、10:15 报告 TRACE、按延迟规则 14:00 才对公众可见。用公众可见时间做事件零点，等于把冲击起点推迟 4 小时；把报告时间当成交时间，零点又早了 15 分钟——三个时钟各答各的问题。</span></p><p><span class="marginnote">时钟精度远低于股票 PTP。债券领先滞后做到秒级已经勉强，不要用 TRACE 去和股票匹配时间做微秒价格发现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据字典页：债券标识（CUSIP）、价格、数量（是否 cap）、买卖侧、交易类型、报告方角色、成交时间字段、报告时间字段、取消/更正标志。清洗：更正应撤销旧报告再应用新报告，不能并列加总。取消未处理会重复计算量。分层：被 cap 的打印单独，因为真量未知，只能当「至少为上限」。</p><p><span class="marginnote">常见误区：把 TRACE 的「打印」当成当时可成交价格的证据。它只是「曾经以某价成交过」的记录；许多债券一天一笔甚至零笔，并不存在可以对着挂单的簿。成本要用配对加价或变现时间来估，而不是对着不存在的中点算价差。</span></p>',13)),(E(),n(i,null,{default:e(()=>[A(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8E%9F%E5%A7%8B%E6%8A%A5%E5%91%8A%20R1%22%5D%20--%3E%20B%7B%22%E5%90%8E%E7%BB%AD%E6%B6%88%E6%81%AF%E7%B1%BB%E5%9E%8B%22%7D%0A%20%20B%20--%20%22%E6%9B%B4%E6%AD%A3%22%20--%3E%20C%5B%22%E6%92%A4%E9%94%80%20R1%20%E5%86%8D%E5%BA%94%E7%94%A8%E6%96%B0%E6%8A%A5%E5%91%8A%22%5D%0A%20%20B%20--%20%22%E5%8F%96%E6%B6%88%22%20--%3E%20E%5B%22%E7%A7%BB%E9%99%A4%20R1%20%E9%87%8F%E5%BD%92%E9%9B%B6%22%5D%0A%20%20B%20--%20%22%E6%97%A0%22%20--%3E%20K%5B%22R1%20%E4%BF%9D%E7%95%99%22%5D%0A%20%20C%20--%3E%20G%5B%22%E6%B1%87%E6%80%BB%E4%B8%8D%E9%87%8D%E5%A4%8D%E8%AE%A1%E8%B4%A6%22%5D%0A%20%20E%20--%3E%20G%0A%20%20K%20--%3E%20G%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>点-in-time：实时策略只能用当时规则下公众可见的字段。事后流动性论文应用增强文件，并声明。把增强文件当实时，是债券版的宏观终值前视。与公司行动：债券赎回、要约会使 CUSIP 生命周期结束，映射要进公司行动引擎，否则幽灵成交。</p><h3 id="与股票馈送对照表" tabindex="-1">与股票馈送对照表 <a class="header-anchor" href="#与股票馈送对照表" aria-label="Permalink to &quot;与股票馈送对照表&quot;">​</a></h3><p>股票：增量簿、序号、匹配时间、保护报价、NBBO。TRACE：离散打印、报告序号（若有）、报告时钟、无公开 BBO、无 NBBO。方向：股票可用 EMO；TRACE 或有侧字段，或仍要推断。有效价差：股票有中点；TRACE 要用配对或基准。把两套字段 join 到同一研究里（资本结构套利）时，对齐的是发行人与日历日，不是微秒事件。</p><p><span class="marginnote">直觉类比：股票磁带像比赛的实时比分直播；TRACE 更像赛后裁判补交的记分表——分数可信，但看不到回合内的攻防，也要等一段时间才公示。用记分表回放比赛节奏，只能到「局」的粒度。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>报告义务改变透明度，从而改变 OTC 议价，这是 Edwards–Harris–Piwowar 的对象。作为馈送，TRACE 的机制是监管收集再分发，延迟与截断是对大额披露的权衡：即时透明伤害存货，完全不透明伤害客户。字段缺失（无深度、无订单）不是数据质量差，是市场结构。把缺失当脏数据填上「中点」，会把债券研究变成错误的股票研究。</p><p>修订：报告方事后更正价格或量，历史文件会变。vintage 原则同样适用：存当时收到的报告，不要只留终版。这与另类数据回填是同一纪律，源是监管磁带。</p><p><span class="marginnote">不要对 TRACE 跑 <a href="/quant/huang-stoll-spread">Huang-Stoll</a> 三路除非你真有连续报价。大多数公司债没有。度量回到配对加价与变现时间。</span></p>',8)),(E(),n(i,null,{default:e(()=>[A(t,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22OTC%20%E6%88%90%E4%BA%A4%E5%8F%91%E7%94%9F%22%5D%20--%3E%20R%5B%22%E5%90%91%20TRACE%20%E6%8A%A5%E5%91%8A%22%5D%0A%20%20R%20--%3E%20CAP%5B%22%E8%A7%84%E6%A8%A1%E6%88%AA%E6%96%AD%20%2F%20%E5%BB%B6%E8%BF%9F%E6%8A%AB%E9%9C%B2%22%5D%0A%20%20CAP%20--%3E%20PUB%5B%22%E5%85%AC%E4%BC%97%E5%8F%AF%E8%A7%81%E6%89%93%E5%8D%B0%22%5D%0A%20%20R%20--%3E%20RES%5B%22%E7%A0%94%E7%A9%B6%E5%A2%9E%E5%BC%BA%E6%96%87%E4%BB%B6%22%5D%0A%20%20PUB%20--%3E%20PIT%5B%22%E5%BD%93%E6%97%B6%E4%BF%A1%E6%81%AF%E9%9B%86%22%5D%0A%20%20RES%20--%3E%20EX%5B%22%E4%BA%8B%E5%90%8E%E6%88%90%E6%9C%AC%E5%BA%A6%E9%87%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h3 id="取消与更正是事件不是脏行" tabindex="-1">取消与更正是事件不是脏行 <a class="header-anchor" href="#取消与更正是事件不是脏行" aria-label="Permalink to &quot;取消与更正是事件不是脏行&quot;">​</a></h3><p>并列加总未撤销的旧报告，会重复计算量与成本。清洗应按报告序号应用更正语义。终版文件若覆盖旧报告，仍应保留 vintage，以免事后度量改写当时信息集。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>非美元债、贷款、CDS 不在 TRACE。中国银行间有自己的报告与披露，不能把 TRACE 字段当模板硬套。可转债可能同时出现在股票磁带与 TRACE，去重要按产品规则，不能简单按 CUSIP 丢弃一侧。本附录对照课序结束。</p><p><span class="marginnote">公众延迟披露的大额，当时不可见。用增强未截断文件去做实时信号，是债券版的宏观终值前视。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TRACE 是报告契约：字段、截断、延迟、更正，不是 LOB。</li><li>成交、报告、公众可见三个时钟必须分开。</li><li>实时策略用当时公众可见字段；事后研究用增强文件并声明。</li><li>取消与更正要当事件处理；cap 量只能当下限。</li><li>与股票 SIP/直连/NBBO 不可类比到同一事件循环。</li><li>出处：FINRA TRACE 公开报告与披露规则；Edwards, Harris and Piwowar, <em>Journal of Finance</em>, 2007；Bessembinder 等对 TRACE 透明度的研究。</li></ul>',7))])}const _=s(p,[["render",d]]);export{m as __pageData,_ as default};
